      "mainEntity": [
        {
          "@type": "Question",
          "name": "Is a cantilevered facade element more expensive than a standard flush facade?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Generally yes, due to the additional structural engineering and typically stronger materials required to safely support a projecting, unsupported edge, particularly as projection distance increases."
          }
        },
        {
          "@type": "Question",
          "name": "How far can a facade element cantilever safely?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "This depends entirely on the specific structural engineering, materials, and loads involved. There's no universal maximum, since it's calculated project by project based on the cantilever's design and the forces acting on it."
          }
        },
        {
          "@type": "Question",
          "name": "Why do cantilevered elements sometimes use steel even when the rest of the facade is aluminium?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Steel's higher strength relative to bending forces makes it well suited to the structural frame of a cantilever, even when a lighter material like aluminium is used for the visible cladding finish on top of that structure."
          }
        },
        {
          "@type": "Question",
          "name": "Do cantilevered facades need special ongoing maintenance?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "They generally don't need more maintenance than a standard facade, but periodic structural inspection is worth including in a building's maintenance plan given the ongoing dynamic loads a cantilevered element carries over its lifetime."
          }
        },
        {
          "@type": "Question",
          "name": "Can a cantilevered element be added to an existing building?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It's possible but requires careful structural assessment of the existing building's capacity to support the new load at the connection point, making it a more involved undertaking than adding flush facade cladding to an existing wall."
          }
        }
